166			result, err := svc.Register(service.RegisterInput{
167				Repository:        input.repository,
168				Digest:            input.digest,
169				Tag:               input.tag,
170				SignatureVerified: input.signatureVerified,
171				RetentionDays:     input.retentionDays,
172				SizeBytes:         input.sizeBytes,
173			})
