17	func newTestService(t *testing.T) (*Service, string) {
18		t.Helper()
19		path := filepath.Join(t.TempDir(), "service.db")
20		st, err := store.Open(path)
21		if err != nil {
22			t.Fatalf("open store: %v", err)
