28	func validInput(repo, digest, tag string) RegisterInput {
29		return RegisterInput{
30			Repository:        repo,
31			Digest:            digest,
32			Tag:               tag,
33			SignatureVerified: true,
34			RetentionDays:     30,
35			SizeBytes:         1024,
36		}
37	}
38	
39	func wantRecord(t *testing.T, got Artifact, in RegisterInput, pushedAt string) {
40		t.Helper()
41		want := Artifact{
42			Repository:        in.Repository,
43			Digest:            in.Digest,
44			Tag:               in.Tag,
45			SignatureVerified: in.SignatureVerified,
46			RetentionDays:     in.RetentionDays,
47			SizeBytes:         in.SizeBytes,
48			PushedAt:          pushedAt,
49		}
50		if got != want {
51			t.Fatalf("record = %+v, want %+v", got, want)
52		}
53	}
54	
55	func assertRFC3339UTC(t *testing.T, value string) {
56		t.Helper()
57		parsed, err := time.Parse(time.RFC3339, value)
58		if err != nil {
59			t.Fatalf("pushed_at %q is not RFC3339: %v", value, err)
60		}
61		if parsed.Location() != time.UTC {
62			t.Fatalf("pushed_at %q is not UTC", value)
63		}
64	}
65	
66	func TestRegisterCreatedThenDuplicate(t *testing.T) {
67		svc, _ := newTestService(t)
68		input := validInput("team/app", digestA, "latest")
69	
70		first, err := svc.Register(input)
71		if err != nil {
72			t.Fatalf("first register: %v", err)
73		}
74		if first.Outcome != OutcomeCreated {
75			t.Fatalf("first outcome = %v, want OutcomeCreated", first.Outcome)
76		}
77		assertRFC3339UTC(t, first.Artifact.PushedAt)
78		wantRecord(t, first.Artifact, input, first.Artifact.PushedAt)
79		pushedAt := first.Artifact.PushedAt
80	
81		// An identical retry is distinguishable as a duplicate and returns the
82		// original record, including its push time.
83		second, err := svc.Register(input)
84		if err != nil {
85			t.Fatalf("duplicate register: %v", err)
86		}
87		if second.Outcome != OutcomeDuplicate {
88			t.Fatalf("duplicate outcome = %v, want OutcomeDuplicate", second.Outcome)
89		}
90		if second.Artifact != first.Artifact {
91			t.Fatalf("duplicate record = %+v, want original %+v", second.Artifact, first.Artifact)
92		}
93		if second.Artifact.PushedAt != pushedAt {
94			t.Fatalf("pushed_at changed on duplicate: %q -> %q", pushedAt, second.Artifact.PushedAt)
95		}
96	}
97	
98	func TestRegisterConflictLeavesRecordAndTagUntouched(t *testing.T) {
99		svc, _ := newTestService(t)
100		input := validInput("team/app", digestA, "latest")
101	
102		first, err := svc.Register(input)
103		if err != nil {
104			t.Fatalf("first register: %v", err)
105		}
106	
107		// Move the tag to B so we can prove a rejected re-registration of A never
108		// moves it back.
109		inputB := validInput("team/app", digestB, "latest")
110		inputB.SizeBytes = 2048
111		if _, err := svc.Register(inputB); err != nil {
112			t.Fatalf("register B: %v", err)
113		}
114	
115		conflicts := map[string]RegisterInput{
116			"changed tag":       withChanges(input, func(in *RegisterInput) { in.Tag = "other" }),
117			"changed signature": withChanges(input, func(in *RegisterInput) { in.SignatureVerified = false }),
118			"changed retention": withChanges(input, func(in *RegisterInput) { in.RetentionDays = 31 }),
119			"changed size":      withChanges(input, func(in *RegisterInput) { in.SizeBytes = 2048 }),
120		}
121		for name, bad := range conflicts {
122			t.Run(name, func(t *testing.T) {
123				if _, err := svc.Register(bad); !errors.Is(err, ErrConflict) {
124					t.Fatalf("register error = %v, want ErrConflict", err)
125				}
126	
127				// The immutable A record is unchanged, including pushed_at.
128				byDigest, err := svc.Query(Query{Kind: QueryByDigest, Repository: "team/app", Digest: digestA})
129				if err != nil {
130					t.Fatalf("query A after conflict: %v", err)
131				}
132				if len(byDigest) != 1 || byDigest[0] != first.Artifact {
133					t.Fatalf("A record changed after conflict: %+v", byDigest)
134				}
135	
136				// The tag still resolves to B.
137				byTag, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "latest"})
138				if err != nil {
139					t.Fatalf("query tag after conflict: %v", err)
140				}
141				if len(byTag) != 1 || byTag[0].Digest != digestB {
142					t.Fatalf("tag pointer moved after conflict: %+v", byTag)
143				}
144	
145				// No third record and registration order is intact.
146				list, err := svc.Query(Query{Kind: QueryByRepository, Repository: "team/app"})
147				if err != nil {
148					t.Fatalf("list after conflict: %v", err)
149				}
150				if len(list) != 2 || list[0].Digest != digestA || list[1].Digest != digestB {
151					t.Fatalf("list changed after conflict: %+v", list)
152				}
153	
154				// The rejected body's tag was never persisted.
155				if _, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "other"}); !errors.Is(err, ErrNotFound) {
156					t.Fatalf("rejected tag lookup error = %v, want ErrNotFound", err)
157				}
158			})
159		}
160	}
161	
162	func withChanges(in RegisterInput, change func(*RegisterInput)) RegisterInput {
163		change(&in)
164		return in
165	}
166	
167	// TestRegistrationSequenceAndQueries walks: register A, register B under the
168	// same tag, retry A, then read through all three query kinds.
169	func TestRegistrationSequenceAndQueries(t *testing.T) {
170		svc, _ := newTestService(t)
171		inputA := validInput("team/app", digestA, "latest")
172		inputB := validInput("team/app", digestB, "latest")
173		inputB.SizeBytes = 2048
174	
175		first, err := svc.Register(inputA)
176		if err != nil {
177			t.Fatalf("register A: %v", err)
178		}
179		if _, err := svc.Register(inputB); err != nil {
180			t.Fatalf("register B: %v", err)
181		}
182		retry, err := svc.Register(inputA)
183		if err != nil {
184			t.Fatalf("retry A: %v", err)
185		}
186		if retry.Outcome != OutcomeDuplicate || retry.Artifact.PushedAt != first.Artifact.PushedAt {
187			t.Fatalf("retry A = %+v, want duplicate with original pushed_at", retry)
188		}
189	
190		// List keeps first-registration order A, B.
191		list, err := svc.Query(Query{Kind: QueryByRepository, Repository: "team/app"})
192		if err != nil {
193			t.Fatalf("list: %v", err)
194		}
195		if len(list) != 2 || list[0].Digest != digestA || list[1].Digest != digestB {
196			t.Fatalf("list = %+v, want [A B] in registration order", list)
197		}
198	
199		// The tag resolves to the newer record B even after retrying A.
200		byTag, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "latest"})
201		if err != nil {
202			t.Fatalf("by tag: %v", err)
203		}
204		if len(byTag) != 1 || byTag[0].Digest != digestB {
205			t.Fatalf("tag = %+v, want B", byTag)
206		}
207	
208		// A is still retrievable by digest, byte for byte the first record.
209		byDigest, err := svc.Query(Query{Kind: QueryByDigest, Repository: "team/app", Digest: digestA})
210		if err != nil {
211			t.Fatalf("by digest: %v", err)
212		}
213		if len(byDigest) != 1 || byDigest[0] != first.Artifact {
214			t.Fatalf("digest lookup = %+v, want original A %+v", byDigest, first.Artifact)
215		}
216	}
