218	func TestRepositoriesDoNotInterfere(t *testing.T) {
219		svc, _ := newTestService(t)
220		inputOne := validInput("repo/one", digestA, "latest")
221		inputTwo := validInput("repo/two", digestA, "latest")
222	
223		if _, err := svc.Register(inputOne); err != nil {
224			t.Fatalf("register repo one: %v", err)
225		}
226		if _, err := svc.Register(inputTwo); err != nil {
227			t.Fatalf("register repo two: %v", err)
228		}
229	
230		one, err := svc.Query(Query{Kind: QueryByTag, Repository: "repo/one", Tag: "latest"})
231		if err != nil {
232			t.Fatalf("repo one tag: %v", err)
233		}
234		two, err := svc.Query(Query{Kind: QueryByTag, Repository: "repo/two", Tag: "latest"})
235		if err != nil {
236			t.Fatalf("repo two tag: %v", err)
237		}
238		if one[0].Repository != "repo/one" || two[0].Repository != "repo/two" {
239			t.Fatalf("tag lookups crossed repositories: %+v %+v", one, two)
240		}
241	
242		// A conflict in repo two leaves repo one's record untouched.
243		conflict := inputTwo
244		conflict.SizeBytes = 4096
245		if _, err := svc.Register(conflict); !errors.Is(err, ErrConflict) {
246			t.Fatalf("cross-repo conflict error = %v, want ErrConflict", err)
247		}
248		oneAgain, err := svc.Query(Query{Kind: QueryByDigest, Repository: "repo/one", Digest: digestA})
249		if err != nil || oneAgain[0].SizeBytes != inputOne.SizeBytes {
250			t.Fatalf("repo one changed after repo two conflict: %+v %v", oneAgain, err)
251		}
252	
253		oneList, err := svc.Query(Query{Kind: QueryByRepository, Repository: "repo/one"})
254		if err != nil {
255			t.Fatalf("repo one list: %v", err)
256		}
257		twoList, err := svc.Query(Query{Kind: QueryByRepository, Repository: "repo/two"})
258		if err != nil {
259			t.Fatalf("repo two list: %v", err)
260		}
261		if len(oneList) != 1 || len(twoList) != 1 {
262			t.Fatalf("lists leaked across repositories: %+v %+v", oneList, twoList)
263		}
264	}
