266	func TestQueryNotFound(t *testing.T) {
267		svc, _ := newTestService(t)
268		if _, err := svc.Register(validInput("team/app", digestA, "latest")); err != nil {
269			t.Fatalf("register: %v", err)
270		}
271	
272		cases := map[string]Query{
273			"unknown repository": {Kind: QueryByRepository, Repository: "other/repo"},
274			"unknown tag":        {Kind: QueryByTag, Repository: "team/app", Tag: "missing"},
275			"unknown digest":     {Kind: QueryByDigest, Repository: "team/app", Digest: digestB},
276		}
277		for name, query := range cases {
278			t.Run(name, func(t *testing.T) {
279				if _, err := svc.Query(query); !errors.Is(err, ErrNotFound) {
280					t.Fatalf("error = %v, want ErrNotFound", err)
281				}
282			})
283		}
