286	func TestStorageFailureIsNotNotFound(t *testing.T) {
287		path := filepath.Join(t.TempDir(), "service.db")
288		st, err := store.Open(path)
289		if err != nil {
290			t.Fatalf("open store: %v", err)
291		}
292		svc := New(st)
293		if _, err := svc.Register(validInput("team/app", digestA, "latest")); err != nil {
294			t.Fatalf("seed register: %v", err)
295		}
296		if err := st.Close(); err != nil {
297			t.Fatalf("close store: %v", err)
298		}
299	
300		// Every operation reports ErrStorage, even lookups that would otherwise hit.
301		if _, err := svc.Register(validInput("team/app", digestB, "latest")); !errors.Is(err, ErrStorage) {
302			t.Fatalf("register error = %v, want ErrStorage", err)
303		}
304		for name, query := range map[string]Query{
305			"list":   {Kind: QueryByRepository, Repository: "team/app"},
306			"tag":    {Kind: QueryByTag, Repository: "team/app", Tag: "latest"},
307			"digest": {Kind: QueryByDigest, Repository: "team/app", Digest: digestA},
308			"miss":   {Kind: QueryByDigest, Repository: "team/app", Digest: digestB},
309		} {
310			t.Run(name, func(t *testing.T) {
311				if _, err := svc.Query(query); !errors.Is(err, ErrStorage) {
312					t.Fatalf("query error = %v, want ErrStorage", err)
313				}
314			})
315		}
316	}
317	
318	// TestRecordsSurviveReopen uses an existing SQLite file without conversion and
319	// checks records, first-registration order, push times and tag pointers.
320	func TestRecordsSurviveReopen(t *testing.T) {
321		path := filepath.Join(t.TempDir(), "service.db")
322	
323		st, err := store.Open(path)
324		if err != nil {
325			t.Fatalf("open store: %v", err)
326		}
327		svc := New(st)
328		inputA := validInput("team/app", digestA, "latest")
329		inputB := validInput("team/app", digestB, "latest")
330		inputB.SizeBytes = 2048
331		first, err := svc.Register(inputA)
332		if err != nil {
333			t.Fatalf("register A: %v", err)
334		}
335		second, err := svc.Register(inputB)
336		if err != nil {
337			t.Fatalf("register B: %v", err)
338		}
339		if err := st.Close(); err != nil {
340			t.Fatalf("close: %v", err)
341		}
342	
343		reopened, err := store.Open(path)
344		if err != nil {
345			t.Fatalf("reopen: %v", err)
346		}
347		t.Cleanup(func() { reopened.Close() })
348		svc = New(reopened)
349	
350		list, err := svc.Query(Query{Kind: QueryByRepository, Repository: "team/app"})
351		if err != nil {
352			t.Fatalf("list after reopen: %v", err)
353		}
354		if len(list) != 2 ||
355			list[0].Digest != digestA || list[0].PushedAt != first.Artifact.PushedAt ||
356			list[1].Digest != digestB || list[1].PushedAt != second.Artifact.PushedAt {
357			t.Fatalf("records/order/timestamps changed after reopen: %+v", list)
358		}
359	
360		byTag, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "latest"})
361		if err != nil {
362			t.Fatalf("tag after reopen: %v", err)
363		}
364		if len(byTag) != 1 || byTag[0].Digest != digestB || byTag[0].PushedAt != second.Artifact.PushedAt {
365			t.Fatalf("tag pointer changed after reopen: %+v", byTag)
366		}
367	
368		byDigest, err := svc.Query(Query{Kind: QueryByDigest, Repository: "team/app", Digest: digestA})
369		if err != nil {
370			t.Fatalf("digest after reopen: %v", err)
371		}
372		if len(byDigest) != 1 || byDigest[0] != first.Artifact {
373			t.Fatalf("A record changed after reopen: %+v", byDigest)
374		}
375	}
