	}
}

func customID(repo, digest string) string { return repo + "\x00" + digest }

func (c *customStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
	if c.fault != nil {
		return service.Record{}, 0, c.fault
	}
